# Write each locale
for loc, data in T.items():
    p = f'content/i18n/{loc}.json'
    with open(p, encoding='utf-8') as f:
        i18n = json.load(f)
    if 'products' not in i18n:
        i18n['products'] = {}
    for slug, content in data.items():
        if slug not in i18n['products']:
            i18n['products'][slug] = {}
        i18n['products'][slug]['description'] = content['description']
        i18n['products'][slug]['features'] = content['features']
    with open(p, 'w', encoding='utf-8') as f:
        json.dump(i18n, f, ensure_ascii=False, indent=2)
    print(f'{loc}: wrote {len(data)} products')

print('Done fr/de/pt.')
